{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table daniel_klein_db.maplemonk.daniel_klien_or_inventory as select TO_DATE(date || \'-\' || year, \'DD-MON-YYYY\') AS inventory_date, upper(trim(sku)) as SKU, \'AMAZON OR\' as data_source, sum(ifnull(cast(trim(qty) as int),0)) as inventory from daniel_klein_db.maplemonk.dk_s3_amazonor_inventory group by 1,2,3 union all select TO_DATE(date || \'-\' || year, \'DD-MON-YYYY\') AS inventory_date, upper(trim(sku)) as SKU, \'FLIPKART OR\' as data_source, sum(ifnull(cast(trim(qty) as int),0)) as inventory from daniel_klein_db.maplemonk.dk_s3_flipkart_inventory group by 1,2,3 union all select TO_DATE(date || \'-\' || year, \'DD-MON-YYYY\') AS inventory_date, upper(trim(sku)) as SKU, \'MYNTRA OR\' as data_source, sum(ifnull(cast(trim(qty) as int),0)) as inventory from daniel_klein_db.maplemonk.dk_s3_myntra_inventory group by 1,2,3 ; create or replace table daniel_klein_db.maplemonk.daniel_klein_inventory_fact_items as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(sku) as sku, marketplace as data_source, SUM(quantity) AS daily_quantity from daniel_klein_db.MAPLEMONK.daniel_klein_db_sales_consolidated s WHERE upper(marketplace) in (\'AMAZON OR\',\'FLIPKART OR\',\'MYNTRA OR\') GROUP BY 1,2,3 ), daily_inventory_snapshot AS ( SELECT TO_DATE(inventory_date) date_day, upper(SKU) sku, data_source, sum(cast(inventory as INT)) as inventory_that_day, CASE WHEN ifnull(sum(cast(inventory as INT)),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(sum(cast(inventory as INT)),0) < 4 THEN 1 ELSE 0 END AS is_oos FROM daniel_klein_db.maplemonk.daniel_klien_or_inventory i where sku <> \'#N/A\' GROUP BY 1,2,3 ORDER BY 1 DESC ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.data_source FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT DATEADD(day, SEQ4(), \'2026-01-01\'::DATE) AS date_day FROM TABLE(GENERATOR(ROWCOUNT => 10000)) WHERE DATEADD(day, SEQ4(), \'2026-01-01\'::DATE) <= CURRENT_DATE() ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, a.data_source, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(i.has_inventory, 0) AS has_inventory_today, inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS L14_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS inventory_days_14, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS oos_days_14, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS oos_days_45 FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku AND a.data_source = s.data_source LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku AND a.data_source = i.data_source order by 1 desc ) SELECT date_day as data_fetch_date, s.sku, s.data_source, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, L7_day_sales sold_quantity_7_days, L14_day_sales sold_quantity_14_days, L30_day_sales sold_quantity_30_days, L45_day_sales sold_quantity_45_days, inventory_days_7, inventory_days_14, inventory_days_30, inventory_days_45, oos_days_7, oos_days_14, oos_days_30, oos_days_45 FROM sales_metrics s ;",
                    "transaction": true
                }
            ) }}
